package com.interview.fraud.ai;
import com.interview.fraud.casework.*; import com.interview.fraud.transaction.TransactionRepository; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Component;
@Component public class ApprovedToolRegistry {public static final Set<String> ALLOWLIST=Set.of("getTransactionDetails","getCustomerProfile","getTransactionHistory","getDeviceHistory","getMerchantRiskProfile","calculateRiskScore","searchFraudPolicies","getRelatedCases");private final TransactionRepository transactions;private final CaseWorkflowService workflow;private final PolicyRagService policies;private final JdbcTemplate jdbc;public ApprovedToolRegistry(TransactionRepository t,CaseWorkflowService w,PolicyRagService p,JdbcTemplate j){transactions=t;workflow=w;policies=p;jdbc=j;}public Object call(String tool,CaseEntity c){if(!ALLOWLIST.contains(tool))throw new SecurityException("Tool is not allowlisted");return switch(tool){case "getTransactionDetails"->CaseView.from(c);case "getTransactionHistory"->Map.of("customerId",c.transaction.customerId,"transactionCount",transactions.countByCustomerId(c.transaction.customerId));case "getDeviceHistory"->Map.of("deviceId",c.transaction.deviceId,"known",false,"note","No prior trusted-device record");case "getMerchantRiskProfile"->Map.of("merchantId",c.transaction.merchantId,"highRisk",Set.of("CRYPTO-9","GAMBLING-7").contains(c.transaction.merchantId));case "calculateRiskScore"->Map.of("score",c.deterministicScore,"signals",workflow.signals(c.id));case "searchFraudPolicies"->policies.search(c.riskLevel+" fraud approval merchant transaction");case "getRelatedCases"->Map.of("count",0,"cases",List.of());case "getCustomerProfile"->Map.of("customerId",c.transaction.customerId,"profileStatus","limited","pii","MASKED");default->throw new SecurityException("Denied");};}}
